1	// Memory-movement component: TMA (Tensor Memory Accelerator) bulk tile load, pure CUDA + inline
2	// PTX (NO cutlass/cute). Replicates what FA3 uses `cute::SM90_TMA_LOAD` / `make_tma_copy` for:
3	//   * host: cuTensorMapEncodeTiled  (CUDA driver) builds the tensor-map descriptor
4	//   * device: cp.async.bulk.tensor.2d.shared::cluster.global ... mbarrier::complete_tx::bytes
5	//             + mbarrier.init / arrive.expect_tx / try_wait.parity
6	//
7	// Validates by TMA-loading every [boxM x boxK] tile of a [M,K] bf16 matrix into smem and writing it
8	// back to global; checks bitwise equality vs the input and reports effective HBM bandwidth. A plain
9	// cp.async copy is timed as a baseline. SWIZZLE_NONE here (the swizzle integration with wgmma is a
10	// separate step); FA3's paged config actually loads K/V via cp.async, Q via TMA.
11	//
12	// Usage: ./tma_load <M> <K> [iters] [trials]
13	
14	#include "oracle_common.cuh"
15	#include <cuda.h>   // CUtensorMap, cuTensorMapEncodeTiled (driver API; link -lcuda)
16	
17	constexpr int BOX_M = 128;
18	constexpr int BOX_K = 64;
19	constexpr int NThreads = 256;
20	
21	// ---- inline-PTX TMA / mbarrier helpers ----
22	__device__ __forceinline__ void mbar_init(uint64_t* bar, int count) {
23	    uint32_t a = (uint32_t)__cvta_generic_to_shared(bar);
24	    asm volatile("mbarrier.init.shared.b64 [%0], %1;\n" :: "r"(a), "r"(count));
25	}
26	__device__ __forceinline__ void mbar_expect_tx(uint64_t* bar, uint32_t bytes) {
27	    uint32_t a = (uint32_t)__cvta_generic_to_shared(bar);
28	    asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;\n"
29	                 :: "r"(a), "r"(bytes) : "memory");
30	}
31	__device__ __forceinline__ void tma_load_2d(void* smem, const CUtensorMap* map,
32	                                            int x, int y, uint64_t* bar) {
33	    uint32_t s = (uint32_t)__cvta_generic_to_shared(smem);
34	    uint32_t b = (uint32_t)__cvta_generic_to_shared(bar);
35	    asm volatile(
36	        "cp.async.bulk.tensor.2d.shared::cluster.global.tile.mbarrier::complete_tx::bytes"
37	        " [%0], [%1, {%2, %3}], [%4];\n"
38	        :: "r"(s), "l"(map), "r"(x), "r"(y), "r"(b) : "memory");
39	}
40	__device__ __forceinline__ bool mbar_try_wait(uint64_t* bar, int phase) {
41	    uint32_t a = (uint32_t)__cvta_generic_to_shared(bar);
42	    uint32_t ok;
43	    asm volatile(
44	        "{\n.reg .pred p;\n"
45	        "mbarrier.try_wait.parity.shared::cta.b64 p, [%1], %2;\n"
46	        "selp.u32 %0, 1, 0, p;\n}\n"
47	        : "=r"(ok) : "r"(a), "r"(phase));
48	    return ok != 0;
49	}
