51	extern __shared__ __nv_bfloat16 tile_smem[];
52	
53	// TMA-load each box tile into smem, write back to global (round-trip correctness + bandwidth).
54	__global__ void tma_roundtrip(const __grid_constant__ CUtensorMap map,
55	                              __nv_bfloat16* __restrict__ out, int M, int K,
56	                              int tiles_m, int tiles_k) {
57	    __shared__ alignas(8) uint64_t bar;
58	    const int tid = threadIdx.x;
59	    const int total = tiles_m * tiles_k;
60	
61	    if (tid == 0) mbar_init(&bar, 1);
62	    __syncthreads();
63	
64	    for (int tile = blockIdx.x; tile < total; tile += gridDim.x) {
65	        const int m0 = (tile / tiles_k) * BOX_M;
66	        const int k0 = (tile % tiles_k) * BOX_K;
67	        if (tid == 0) {
68	            tma_load_2d(tile_smem, &map, k0, m0, &bar);      // coords: {inner=K, outer=M}
69	            mbar_expect_tx(&bar, BOX_M * BOX_K * sizeof(__nv_bfloat16));
70	        }
71	        // phase flips every completed tile; track parity = #tiles done so far for this block.
72	        int phase = ((tile - blockIdx.x) / gridDim.x) & 1;
73	        while (!mbar_try_wait(&bar, phase)) {}
74	        // smem holds the box row-major (inner K contiguous): smem[m*BOX_K + k].
75	        for (int i = tid; i < BOX_M * BOX_K; i += NThreads) {
76	            int m = i / BOX_K, k = i % BOX_K;
77	            out[(size_t)(m0 + m) * K + (k0 + k)] = tile_smem[m * BOX_K + k];
78	        }
79	        __syncthreads();   // tile reused next iteration
80	    }
81	}
