83	// cp.async baseline: same round-trip via float4 global->smem->global.
84	__global__ void cpasync_roundtrip(const __nv_bfloat16* __restrict__ in,
85	                                  __nv_bfloat16* __restrict__ out, int M, int K,
86	                                  int tiles_m, int tiles_k) {
87	    const int tid = threadIdx.x;
88	    const int total = tiles_m * tiles_k;
89	    for (int tile = blockIdx.x; tile < total; tile += gridDim.x) {
90	        const int m0 = (tile / tiles_k) * BOX_M;
91	        const int k0 = (tile % tiles_k) * BOX_K;
92	        for (int i = tid; i < BOX_M * (BOX_K / 8); i += NThreads) {
93	            int m = i / (BOX_K / 8), kc = (i % (BOX_K / 8)) * 8;
94	            uint32_t s = (uint32_t)__cvta_generic_to_shared(&tile_smem[m * BOX_K + kc]);
95	            const void* g = &in[(size_t)(m0 + m) * K + (k0 + kc)];
96	            asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(s), "l"(g));
97	        }
98	        asm volatile("cp.async.commit_group;\n");
99	        asm volatile("cp.async.wait_group 0;\n");
100	        __syncthreads();
101	        for (int i = tid; i < BOX_M * (BOX_K / 8); i += NThreads) {
102	            int m = i / (BOX_K / 8), kc = (i % (BOX_K / 8)) * 8;
103	            *reinterpret_cast<float4*>(&out[(size_t)(m0 + m) * K + (k0 + kc)]) =
104	                *reinterpret_cast<float4*>(&tile_smem[m * BOX_K + kc]);
105	        }
106	        __syncthreads();
107	    }
108	}
