1	// Isolated validation of the MN-major 128B-swizzle <-> wgmma-descriptor <-> TMA integration for the V
2	// operand (PV GEMM). O[128,128] = P[128,128] @ V[128,128], bf16 operands, fp32 acc.
3	//   P : A operand, K-major (keys contiguous)   -> K-major B128 desc (LBO=16B, SBO=1024B), trans-a=0
4	//   V : B operand, MN-major (dv  contiguous)   -> MN-major B128 desc (LBO=1024B, SBO=2048B), trans-b=1
5	// Both ground-truthed from cute (swz_probe.cu): MN k-step (over keys) = kb*2048 elems = kb*4096 B.
6	// Path B (the one the real kernel uses): TMA-load P,V with CU_TENSOR_MAP_SWIZZLE_128B (single box,
7	// inner = contiguous extent = 128 elems = 256B, exactly as cute/FA3 encode it) -> wgmma -> vs CPU ref.
8	#include "oracle_common.cuh"
9	#include <cuda.h>
