11	constexpr int M = 128, KEYS = 128, DV = 128;
12	
13	__device__ __host__ __forceinline__ int swz(int o) { return o ^ (((o >> 7) & 7) << 4); }
14	// element (mn,k) of a [128,K] K-major SW128 tile (used for the P / A operand)
15	__device__ __host__ __forceinline__ int koff(int mn, int k) { return (k >> 6) * 8192 + swz(mn * 64 + (k & 63)); }
