17	__device__ __forceinline__ uint64_t make_desc(uint32_t a, uint32_t lbo, uint32_t sbo, uint32_t lt) {
18	    uint64_t d = 0;
19	    d |= (uint64_t)((a >> 4) & 0x3FFFu);
20	    d |= (uint64_t)((lbo >> 4) & 0x3FFFu) << 16;
21	    d |= (uint64_t)((sbo >> 4) & 0x3FFFu) << 32;
22	    d |= (uint64_t)(lt & 0x3u) << 62;
23	    return d;
24	}
