48	__device__ __forceinline__ void pv_gemm_sw(float (&o)[64], uint32_t sP_wg, uint32_t sV_base) {
49	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
50	#pragma unroll
51	    for (int kb = 0; kb < 8; ++kb) {
52	        uint32_t kstepP = (uint32_t)(((kb & 3) * 16 + (kb >> 2) * 8192) * 2);  // bytes, K-major (P)
53	        uint32_t kstepV = (uint32_t)(kb * 4096);                               // bytes, MN-major (V)
54	        uint64_t dA = make_desc(sP_wg   + kstepP, 16, 1024, 1);               // K-major B128
55	        uint64_t dB = make_desc(sV_base + kstepV, 1024, 2048, 1);             // MN-major B128
56	        int scaleD = (kb == 0) ? 0 : 1;
