79	__device__ __forceinline__ void store_O(float (&o)[64], float* Og, int cwg, int warp, int lane) {
80	    int group = lane >> 2, tg = lane & 3;
81	    int row_lo = cwg * 64 + warp * 16 + group, row_hi = row_lo + 8;
