1	// CUTLASS SM90 warp-specialized GEMM oracle.
2	//
3	// Reproduces the FA3 hd128-bf16 prefill GEMM building blocks as a *standalone* CUTLASS GEMM
4	// so we can (a) inspect the generated PTX/SASS (wgmma + TMA + mbarrier) and (b) get the
5	// CUTLASS latency/output to match with a pure-CUDA/PTX kernel.
6	//
7	//   GEMM_MODE=QK : C[M,N] = A[M,K] . B[N,K]^T   (A row-major, B row-major => "TN")  K=head_dim
8	//   GEMM_MODE=PV : C[M,N] = A[M,K] . B[K,N]      (A row-major, B row-major => "NN")  N=head_dim_v
9	//
10	// bf16 inputs, fp32 accumulate, fp32 output. Build with: -DGEMM_MODE_QK or -DGEMM_MODE_PV.
11	//
12	// Usage: ./cutlass_gemm <M> <N> <K> [out.bin] [iters] [trials]
13	
14	#include <iostream>
15	#include <string>
16	
17	#include "cutlass/cutlass.h"
18	#include "cute/tensor.hpp"
19	#include "cutlass/gemm/collective/collective_builder.hpp"
20	#include "cutlass/epilogue/collective/collective_builder.hpp"
21	#include "cutlass/gemm/device/gemm_universal_adapter.h"
22	#include "cutlass/gemm/kernel/gemm_universal.hpp"
23	#include "cutlass/util/packed_stride.hpp"
24	
25	#include "oracle_common.cuh"
26	
27	using namespace cute;
28	
29	using Element  = cutlass::bfloat16_t;
30	using ElementAcc = float;
31	using ElementOut = float;
32	
33	#if defined(GEMM_MODE_PV)
34	//  PV: C[M,N] = A[M,K] . B[K,N], both row-major  (NN)
35	using LayoutA = cutlass::layout::RowMajor;
36	using LayoutB = cutlass::layout::RowMajor;
37	static const char* kModeName = "PV";
38	#else
39	//  QK: C[M,N] = A[M,K] . B[N,K]^T  => B stored row-major (N,K) == column-major (K,N)  (TN)
40	using LayoutA = cutlass::layout::RowMajor;
41	using LayoutB = cutlass::layout::ColumnMajor;
42	static const char* kModeName = "QK";
43	#endif
44	using LayoutC = cutlass::layout::RowMajor;
45	
46	constexpr int AlignA = 128 / cutlass::sizeof_bits<Element>::value;     // 8
47	constexpr int AlignB = 128 / cutlass::sizeof_bits<Element>::value;     // 8
48	constexpr int AlignC = 128 / cutlass::sizeof_bits<ElementOut>::value;  // 4
49	
50	using TileShape    = Shape<_128, _128, _64>;   // CTA tile (wgmma stays m64nNk16 underneath)
51	using ClusterShape = Shape<_1, _1, _1>;        // FA3 prefill (varlen) uses no cluster
52	
53	using CollectiveEpilogue = typename cutlass::epilogue::collective::CollectiveBuilder<
54	    cutlass::arch::Sm90, cutlass::arch::OpClassTensorOp,
55	    TileShape, ClusterShape,
56	    cutlass::epilogue::collective::EpilogueTileAuto,
57	    ElementAcc, ElementAcc,
58	    ElementOut, LayoutC, AlignC,
59	    ElementOut, LayoutC, AlignC,
60	    cutlass::epilogue::collective::EpilogueScheduleAuto
61	  >::CollectiveOp;
62	
63	using CollectiveMainloop = typename cutlass::gemm::collective::CollectiveBuilder<
64	    cutlass::arch::Sm90, cutlass::arch::OpClassTensorOp,
65	    Element, LayoutA, AlignA,
66	    Element, LayoutB, AlignB,
67	    ElementAcc,
68	    TileShape, ClusterShape,
69	    cutlass::gemm::collective::StageCountAutoCarveout<
70	      static_cast<int>(sizeof(typename CollectiveEpilogue::SharedStorage))>,
71	    cutlass::gemm::collective::KernelScheduleAuto
72	  >::CollectiveOp;
73	
74	using GemmKernel = cutlass::gemm::kernel::GemmUniversal<
75	    Shape<int, int, int, int>, CollectiveMainloop, CollectiveEpilogue>;
76	using Gemm = cutlass::gemm::device::GemmUniversalAdapter<GemmKernel>;
77	
78	using StrideA = typename Gemm::GemmKernel::StrideA;
79	using StrideB = typename Gemm::GemmKernel::StrideB;
80	using StrideC = typename Gemm::GemmKernel::StrideC;
81	using StrideD = typename Gemm::GemmKernel::StrideD;
82	
83	int main(int argc, char** argv) {
84	    int M = argc > 1 ? std::atoi(argv[1]) : 2048;
85	    int N = argc > 2 ? std::atoi(argv[2]) : 2048;
86	    int K = argc > 3 ? std::atoi(argv[3]) : 128;
87	    std::string out_path = argc > 4 ? argv[4] : "";
88	    int iters  = argc > 5 ? std::atoi(argv[5]) : 100;
89	    int trials = argc > 6 ? std::atoi(argv[6]) : 7;
90	
91	    // ---- deterministic bf16 inputs (shared with the pure-CUDA kernel) ----
92	    std::vector<uint16_t> hA, hB;
93	    orc::fill_bf16(hA, size_t(M) * K, /*seed=*/1);
94	    orc::fill_bf16(hB, size_t(N) * K, /*seed=*/2);  // B is N*K elements either layout
95	
96	    Element *dA, *dB; ElementOut *dC, *dD;
97	    ORC_CHECK(cudaMalloc(&dA, sizeof(Element) * size_t(M) * K));
98	    ORC_CHECK(cudaMalloc(&dB, sizeof(Element) * size_t(N) * K));
99	    ORC_CHECK(cudaMalloc(&dC, sizeof(ElementOut) * size_t(M) * N));
100	    ORC_CHECK(cudaMalloc(&dD, sizeof(ElementOut) * size_t(M) * N));
101	    ORC_CHECK(cudaMemcpy(dA, hA.data(), sizeof(Element) * size_t(M) * K, cudaMemcpyHostToDevice));
102	    ORC_CHECK(cudaMemcpy(dB, hB.data(), sizeof(Element) * size_t(N) * K, cudaMemcpyHostToDevice));
103	
104	    StrideA stride_A = cutlass::make_cute_packed_stride(StrideA{}, cute::make_shape(M, K, 1));
105	    StrideB stride_B = cutlass::make_cute_packed_stride(StrideB{}, cute::make_shape(N, K, 1));
106	    StrideC stride_C = cutlass::make_cute_packed_stride(StrideC{}, cute::make_shape(M, N, 1));
107	    StrideD stride_D = cutlass::make_cute_packed_stride(StrideD{}, cute::make_shape(M, N, 1));
108	
109	    typename Gemm::Arguments args{
